        return activePriceRanges.some(range => {
          switch (range) {
            case 'budget':
              return room.pricing.basePrice <= 60000;
            case 'mid':
              return room.pricing.basePrice > 60000 && room.pricing.basePrice <= 90000;
            case 'premium':
              return room.pricing.basePrice > 90000;
            default:
              return true;
          }
        });
      });
    }
    // Filtrar por calificación
    if (this.currentFilters.minRating) {
